import json,collections,pathlib,hashlib,shutil
p=pathlib.Path('/tmp/awm-rule-audit'); p.mkdir(exist_ok=True)
source=pathlib.Path('data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl')
shutil.copyfile(source,p/'original.jsonl')
r=[json.loads(x) for x in source.open()]
g=collections.defaultdict(list)
for i,x in enumerate(r): g[x['scenario'],x['task_idx']].append((i,x))
print('empty raw_response count',sum(not x['verification'].get('raw_response') for x in r))
for k,v in g.items():
 if len(v)>1:
  stem=f'{k[0]}_{k[1]}'
  for label,(i,x) in zip(['first','later'],v):
   (p/f'{stem}.{label}.py').write_text(x['verification']['code'])
  print(stem,'lines',[(i+1,len(x['verification']['code'].splitlines())) for i,x in v])
  print('TASK:',v[0][1]['task'])
manifest={str(x):hashlib.sha256(x.read_bytes()).hexdigest() for x in pathlib.Path('logs').rglob('*') if x.is_file()}
(p/'logs-sha256.json').write_text(json.dumps(manifest))
PY","workdir":"/workspace","max_output_tokens":4000}));

