for i,x in enumerate(r):
 try: compile(x['verification']['code'],f'rule {i+1}','exec')
 except SyntaxError as e: errors.append((i+1,x['scenario'],x['task_idx'],str(e)))
print('syntax errors',len(errors));print(errors[:30])
keys={(x['scenario'],x['task_idx']) for x in r[10000:]}
tasks={x['task']: (x['scenario'],x['task_idx']) for x in r if (x['scenario'],x['task_idx']) in keys}
for step in [1,150,175,190,199,200]:
 rows=[json.loads(x) for x in open(f'logs/rollouts/{step}.jsonl')];tr=collections.defaultdict(list)
 for x in rows: tr[x['traj_uid']].append(x)
 print('STEP',step,'rows',len(rows),'trajectories',len(tr),'max_steps',sum(len(v)>=20 for v in tr.values()),'invalid rows',sum(not x['is_action_valid'] for x in rows))
 for uid,v in tr.items():
  v.sort(key=lambda x:x['step_num']); first=v[0]['obs_text_base'];task=first.split('User task:\n')[-1].strip()
  if task in tasks:
   print('target',tasks[task],'score',v[-1]['score'],'turns',len(v),'uid',uid,'final',v[-1]['output'][:400])
