from pathlib import Path
import json,textwrap
D=Path('/tmp/awm-rule-audit')
repairs={}
HEADER='''def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    import json
    import math
    from datetime import datetime, date, time, timedelta, timezone
    from contextlib import closing

    def query(path, sql, params=()):
        # Missing tables/columns must fail the check, not masquerade as empty results.
        with closing(sqlite3.connect("file:" + str(path) + "?mode=ro", uri=True)) as conn:
            conn.row_factory = sqlite3.Row
            return conn.execute(sql, params).fetchall()

    def ids(path, table):
        return {r[0] for r in query(path, 'SELECT id FROM "' + table + '"')}

    def dt(value):
        result = datetime.fromisoformat(str(value).strip().replace('Z', '+00:00'))
        return result.replace(tzinfo=timezone.utc) if result.tzinfo is None else result.astimezone(timezone.utc)

    def close(a, b, tolerance=0.01):
        return math.isfinite(float(a)) and abs(float(a) - float(b)) <= tolerance

    def outcome(ok):
        return {"result": "complete" if ok else "others"}

    text = re.sub(r'[`*]', '', final_answer or '')
    def json_answer():
        # Accept plain JSON and JSON embedded in a fenced/explanatory answer.
        decoder = json.JSONDecoder()
        for match in re.finditer(r'[\\[{]', text):
            try:
                obj, _ = decoder.raw_decode(text[match.start():])
                return obj
            except ValueError:
                pass
        return None

    def numbers(value):
        return [float(x.replace(',', '')) for x in re.findall(r'(?<![\\w.])-?\\d[\\d,]*(?:\\.\\d+)?(?![\\w.])', value)]

    def labeled_value(value, labels):
        # Associate a value with its own label, never an unrelated number elsewhere.
        pattern = r'(?:' + labels + r')[\\s_]*(?:[\\"\\\']?\\s*[:=|—–-]?\\s*(?:is|are|of)?\\s*[$]?)\\s*(-?\\d[\\d,]*(?:\\.\\d+)?)(?![\\w.])'
        values = [float(m.group(1).replace(',', '')) for m in re.finditer(pattern, value, re.I)]
        return values[0] if values and all(close(x, values[0]) for x in values) else None

    try:
'''

def custom(key, body):
    code=HEADER+textwrap.indent(textwrap.dedent(body).strip()+'\n','        ')+'''    except (sqlite3.Error, ValueError, TypeError, KeyError, IndexError, OverflowError):
        return {"result": "others"}
'''
    compile(code,str(key),'exec');repairs[key]=code

def edit(key, transform, later=False):
    path=D/f'{key[0]}_{key[1]}.{ "later" if later else "first"}.py'
    code=transform(path.read_text());compile(code,str(key),'exec');repairs[key]=code

# Creation checks must select the newly created object, not the first matching seed row.
def new_candidate(code, table, variable, line):
    insert=f'''    initial_ids = {{row[0] for row in safe_query(initial_db_path, "SELECT id FROM {table}")}}
    {variable} = [row for row in {variable} if row[0] not in initial_ids]
'''
    assert line in code
    return code.replace(line,insert+'\n'+line,1)

edit(('discussion_forum_2',0),lambda c:new_candidate(c,'threads','threads','    if not threads or len(threads) == 0:'))
edit(('stock_trading_1',2),lambda c:new_candidate(c,'watchlists','watchlist_result','    if not watchlist_result:'))
edit(('logistics_and_shipment_tracking_1',0),lambda c:new_candidate(c,'shipments','shipment_result','    if not shipment_result:').split('    # Check if this shipment existed in initial database')[0]+'    return {"result": "complete"}\n')

custom(('iot_device_management_3',5),'''
required = {'vm-COOLER-200', 'vm-COOLER-300'}
old_fw = ids(initial_db_path, 'firmware_versions')
old_jobs = ids(initial_db_path, 'firmware_update_jobs')
for fw in query(final_db_path, "SELECT id FROM firmware_versions WHERE version_code='2.3.5' AND release_channel='stable'"):
    if fw['id'] in old_fw:
        continue
    models = {r[0] for r in query(final_db_path, 'SELECT device_model_id FROM firmware_version_compatibility WHERE firmware_version_id=?', (fw['id'],))}
    if models != required:
        continue
    covered = set()
    for job in query(final_db_path, 'SELECT * FROM firmware_update_jobs WHERE firmware_version_id=?', (fw['id'],)):
        if job['id'] in old_jobs or job['release_channel'] != 'stable' or job['target_site_type'] != 'factory' or job['target_device_status'] != 'active':
            continue
        if job['state'] != 'scheduled':
            continue
        if dt(job['rollout_start_at']) != dt('2026-01-02T01:00:00Z') or dt(job['rollout_end_at']) != dt('2026-01-02T04:00:00Z'):
            continue
        model = job['target_device_model_id']
        covered.update(required if model is None else {model})
    if covered == required:
        return outcome(True)
return outcome(False)
''')

custom(('task_management_16',8),'''
boards = query(final_db_path, "SELECT id,name FROM boards WHERE name IN ('Paid Social Campaigns','Email Campaigns')")
if {r['name'] for r in boards} != {'Paid Social Campaigns','Email Campaigns'}:
    return outcome(False)
bids = {r['id'] for r in boards}
columns = query(final_db_path, 'SELECT id,board_id,name FROM columns')
expected_columns = {name:{r['id'] for r in columns if r['board_id'] in bids and r['name']==name} for name in ['Status','Start Date','End Date']}
old = ids(initial_db_path, 'dashboards')
for dashboard in query(final_db_path, "SELECT id FROM dashboards WHERE name='Marketing Campaign Overview'"):
    did = dashboard['id']
    if did in old:
        continue
    linked = {r[0] for r in query(final_db_path,'SELECT board_id FROM dashboard_boards WHERE dashboard_id=?',(did,))}
    if linked != bids:
        continue
    good = set()
    for w in query(final_db_path,'SELECT widget_type,settings_json FROM widgets WHERE dashboard_id=?',(did,)):
        s = json.loads(w['settings_json'] or '{}')
        if {int(x) for x in s.get('boards',[])} != bids:
            continue
        kind = w['widget_type']
        if kind in ('numbers','chart') and 'status_column_ids' in s and {int(x) for x in s['status_column_ids']} != expected_columns['Status']:
            continue
        if kind == 'numbers' and str(s.get('status_value','')).lower() == 'launched' and s.get('metric','count') == 'count':
            good.add(kind)
        elif kind == 'chart' and str(s.get('group_by','')).lower() == 'status' and s.get('metric','count') == 'count':
            good.add(kind)
        elif kind == 'timeline':
            active = {str(x).lower() for x in s.get('filter_status',[])}
            if ({int(x) for x in s.get('start_date_columns',[])} == expected_columns['Start Date'] and
                {int(x) for x in s.get('end_date_columns',[])} == expected_columns['End Date'] and
                'launched' in active and active <= {'planned','scheduled','launched','in progress','active'}):
                good.add(kind)
    if good == {'numbers','chart','timeline'}:
        return outcome(True)
return outcome(False)
''')

custom(('booking_and_reservations_3',3),'''
old_walk = ids(initial_db_path, 'walk_ins')
old_wait = ids(initial_db_path, 'waitlist_entries')
for w in query(final_db_path, "SELECT * FROM walk_ins WHERE guest_name='Walkin Smith' AND contact_info='smith@example.com' AND party_size=3 AND estimated_wait_minutes=25"):
    # The API documents higher numbers as higher priority; the seed's high tier is 5.
    if w['id'] in old_walk or w['priority_level'] < 5:
