# Preserve the corrected ledger's complete-month computation and require every metric.
# Its unused duplicate was already stricter; bind time to initial state and fix decimal parsing.
def ledger_fix(c):
    c=c.replace('ref_dt = max_timestamp_from_db(final_db_path)','ref_dt = max_timestamp_from_db(initial_db_path)')
    c=c.replace('int(promised_amount)','float(promised_amount)')
    # The seed uses integer money values. Keep their full value, including cents in responses.
    c=c.replace('digits = re.sub(r"[^0-9]", "", grp)','digits = re.sub(r"[^0-9.]", "", grp)')
    c=c.replace('if digits.isdigit():','if re.fullmatch(r"[0-9]+(?:\\.[0-9]+)?", digits):').replace('return int(digits)','return float(digits)')
    c=c.replace('[0-9][0-9,]*)','[0-9][0-9,]*(?:\\.[0-9]+)?)')
    return c
